const AUDIO = [{"id": "experiences", "level": "b1", "source": "https://elllo.org/grammar/B1-07-Present-Perfect-Experiences-Katie-International.htm", "audioSource": "https://elllo.org/Audio/AGTK/B1-07-Present-Perfect-Katie-International.mp3", "audio": "audio/experiences.mp3", "duration": 322.35, "waveform": [49, 38, 44, 34, 39, 35, 38, 36, 38, 46, 46, 40, 38, 40, 41, 44, 38, 41, 38, 44, 40, 40, 41, 36, 37, 45, 40, 45, 43, 38, 44, 39, 40, 23, 56, 49, 43, 52, 52, 43, 42, 51, 48, 49, 42, 42, 45, 42, 38, 49, 39, 52, 47, 42, 46, 37, 41, 42, 41, 39, 39, 44, 36, 32, 40, 46, 51, 40, 33, 38, 44, 43], "transcript": [{"speaker": "Todd", "text": "OK, Katie."}, {"speaker": "Katie", "text": "Yeah."}, {"speaker": "Todd", "text": "Let's take an international test."}, {"speaker": "Katie", "text": "Oh, OK."}, {"speaker": "Todd", "text": "How international are you? Let's find out."}, {"speaker": "Katie", "text": "Let's find out."}, {"speaker": "Todd", "text": "First, have you ever eaten Greek food?"}, {"speaker": "Katie", "text": "Greek food? Ah, I've eaten, how do you say it, falafel."}, {"speaker": "Todd", "text": "Oh, is that Greek?"}, {"speaker": "Katie", "text": "I think so. I've had that, but apart from that, I've never eaten Greek food. How about you?"}, {"speaker": "Todd", "text": "Ah, I think I have. Like, I've eaten Greek yogurt. Does that count?"}, {"speaker": "Katie", "text": "That counts."}, {"speaker": "Todd", "text": "That counts?"}, {"speaker": "Katie", "text": "That counts."}, {"speaker": "Todd", "text": "OK, have you ever eaten Vietnamese food?"}, {"speaker": "Katie", "text": "Ah, I see it written down. Is it pho?"}, {"speaker": "Todd", "text": "Pho, the noodles?"}, {"speaker": "Katie", "text": "Yeah, I've eaten pho before."}, {"speaker": "Todd", "text": "Yeah, I've been to Vietnam so I've eaten Vietnamese food a lot. And pho the noodles is really good."}, {"speaker": "Katie", "text": "Yeah, it's delicious."}, {"speaker": "Todd", "text": "I've had that too."}, {"speaker": "Katie", "text": "OK, now let's talk about languages."}, {"speaker": "Todd", "text": "Oh, OK. Have you ever studied French?"}, {"speaker": "Katie", "text": "I have. I studied French for five years."}, {"speaker": "Todd", "text": "Oh, can you still speak French?"}, {"speaker": "Katie", "text": "Nope. Not at all."}, {"speaker": "Todd", "text": "Yeah, me too. I once studied French years ago, but I haven't spoken French in so long I can't remember anything."}, {"speaker": "Katie", "text": "I can't remember anything either."}, {"speaker": "Todd", "text": "Have you ever studied an Asian Language?"}, {"speaker": "Katie", "text": "I've studied Japanese. I can still speak it a little bit now, and I studied a little bit of Korean, but I don't speak Korean."}, {"speaker": "Todd", "text": "Oh, really. OK. Wow, like I've studied Thai because I lived in Thailand for five years, and like you I've studied Japanese, but my Japanese is terrible."}, {"speaker": "Katie", "text": "How about your Thai?"}, {"speaker": "Todd", "text": "My Thai is OK. It's OK. I can talk a little bit. OK, so have you ever met a Spanish person?"}, {"speaker": "Katie", "text": "A Spanish person? Actually, I don't think I have."}, {"speaker": "Todd", "text": "Really?"}, {"speaker": "Katie", "text": "I don't think I have met a Spanish person."}, {"speaker": "Todd", "text": "Oh, interesting. I've been to Spain so, I've met a few and we have a Spanish teacher at our school."}, {"speaker": "Katie", "text": "Oh, maybe I have met a Spanish person then. Maybe, I've met a secret Spanish person."}, {"speaker": "Todd", "text": "OK, have you met a Chinese person?"}, {"speaker": "Katie", "text": "Oh, yes, I've meet lots of Chinese people."}, {"speaker": "Todd", "text": "OK, and have you met a Brazilian person?"}, {"speaker": "Katie", "text": "I feel like if I say no, then I have. Probably. Probably, I've met a Brazilian person."}, {"speaker": "Todd", "text": "Yeah, I've met a few people from Brazil, so they're alway very nice. Very friendly people."}], "speakerEvidence": [], "sourceLevelText": "", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "job-advice", "level": "b1", "source": "https://elllo.org/english/grammar/B1-05-Should-Suggestions.htm", "audioSource": "https://elllo.org/Audio/AGTK/B1-05-Should-Sarah-Gov-Job.mp3", "audio": "audio/job-advice.mp3", "duration": 312.95, "waveform": [42, 40, 33, 39, 39, 37, 56, 53, 52, 42, 44, 41, 42, 51, 43, 37, 38, 50, 41, 45, 45, 38, 46, 44, 46, 34, 37, 41, 33, 47, 34, 34, 40, 34, 44, 44, 39, 45, 38, 43, 39, 38, 43, 43, 41, 39, 37, 35, 39, 39, 48, 42, 44, 46, 40, 40, 32, 39, 34, 55, 53, 41, 45, 43, 46, 38, 40, 42, 45, 37, 46, 43], "transcript": [{"speaker": "Todd", "text": "So Sara, we're both English teachers, and we taught together before, and then you went away and you worked for the US State Department, and you came back, and now I want to work for the US State Department."}, {"speaker": "Sarah", "text": "You should do it!"}, {"speaker": "Todd", "text": "So I want you to give me some advice what I should do and what I shouldn't do to get the job, and what do I need to do so I can work for the US State Department? So what should I do?"}, {"speaker": "Sarah", "text": "So the first thing you should do is to start doing the paperwork. There is so much paperwork, and it can be overwhelming, so you shouldn't try to do everything in one day, and you shouldn't leave it to the last minute. So please start the paperwork soon."}, {"speaker": "Todd", "text": "Okay, so how long does it take to do the paperwork?"}, {"speaker": "Sarah", "text": "It takes a couple of weeks, because you need to write some very long answers to many different questions, 'cause you need to ask references to write these long, long answers for you."}, {"speaker": "Todd", "text": "Okay, so, who should I ask to be a reference?"}, {"speaker": "Sarah", "text": "You should ask two people who have experience with your teaching. So, for me, I asked the head of the language department, and a co-worker who had observed my class. So you should ask, perhaps, the level coordinator, you should ask your boss, your manager, and then maybe a co-worker who has seen your teaching."}, {"speaker": "Todd", "text": "Okay, so could I ask you?"}, {"speaker": "Sarah", "text": "Yeah! I'd be happy to do that."}, {"speaker": "Todd", "text": "Okay, that's awesome. So you said there's some questions. What's a sample question?"}, {"speaker": "Sarah", "text": "A lot of the questions are about how do you deal with cultural differences. So it might say, \"Tell me a time in your life you have been confused about the culture, and you didn't know how to proceed.\""}, {"speaker": "Todd", "text": "Oh, okay."}, {"speaker": "Sarah", "text": "So you need to write about what happened, and how you overcame it."}, {"speaker": "Todd", "text": "So how should I answer the question? Should I just talk about my own experience?"}, {"speaker": "Sarah", "text": "Mm-hmm."}, {"speaker": "Todd", "text": "Or should I try to phrase it in a way that I think they want to hear? What should I do?"}, {"speaker": "Sarah", "text": "The most important thing is to be honest, but what they're looking for are people who are flexible, understanding, and hard-working. So if you can phrase it in that way, talk about how you really responded to the situation. If you responded poorly, what did you learn from it? How you could have done better, or things like that."}, {"speaker": "Todd", "text": "Okay. Wow, those are some good tips. Is there anything I shouldn't do, I shouldn't say, I shouldn't mention?"}, {"speaker": "Sarah", "text": "Well, just like any job, you shouldn't mention that you want the job just so you could travel, or you want the job just to make some money. You should talk about the more positive aspects of why you want the job ... to help people, to teach people about the culture of the USA, to help people learn English. One of the big reasons this program exists is to spread goodwill about the USA. So we are definitely representatives for the US Government, for the US people, so we need to show that we can be a responsible, kind, hard-working representative of the USA. So they really want to see that in your application as well."}, {"speaker": "Todd", "text": "Okay. Now, as you know, I have elllo, we're doing this for elllo right now. Should I mention elllo? Should I mention that I do elllo? Or should I keep that a secret and not let them know?"}, {"speaker": "Sarah", "text": "I think they would be very happy to hear about elllo, because they desperately want more people how know about technology, online learning, internet and things like that, because the people who apply, a lot of them are like me. We have a masters in TESOL, we are ... I don't mean to brag, but we are good teachers, we're passionate, but they desperately need more people that can help teach things like online learning, technical English, how to set up a website in English ... maybe you could teach that. They want people who have experience and knowledge, and if you can show them your website, I think that they would be really happy to see it."}, {"speaker": "Todd", "text": "Oh wow, that's great. Well thanks for the advice. I'm going to apply!"}, {"speaker": "Sarah", "text": "Yeah, you're welcome! You can do it!"}, {"speaker": "Todd", "text": "All right, wish me luck."}, {"speaker": "Sarah", "text": "Good luck!"}], "speakerEvidence": [], "sourceLevelText": "Should for Suggestions", "originalTitle": "Getting a Job with Uncle Sam"}, {"id": "morning", "level": "b1", "source": "https://elllo.org/english/1301/T1331-amy-morning-routine.htm", "audioSource": "https://elllo.org/Audio/A1301/1331-amy-morning-routine.mp3", "audio": "audio/morning.mp3", "duration": 164.26, "waveform": [12, 41, 52, 47, 44, 39, 35, 30, 32, 34, 29, 29, 27, 31, 36, 35, 31, 40, 29, 36, 42, 46, 31, 41, 27, 26, 32, 31, 29, 32, 32, 33, 44, 56, 46, 38, 29, 27, 30, 35, 25, 26, 28, 32, 33, 27, 40, 31, 30, 32, 44, 38, 42, 33, 43, 32, 26, 29, 28, 26, 26, 24, 36, 38, 34, 30, 20, 27, 44, 40, 25, 11], "transcript": [{"speaker": "Paul", "text": "Hi, Aimee."}, {"speaker": "Aimee", "text": "Hi."}, {"speaker": "Paul", "text": "How are you?"}, {"speaker": "Aimee", "text": "I'm all right. Thanks. How are you?"}, {"speaker": "Paul", "text": "Yeah, pretty good. I was thinking the other day about routine. I mean, do you follow like a strict routine?"}, {"speaker": "Aimee", "text": "Not really. I'm pretty laid-back, I think."}, {"speaker": "Paul", "text": "I see."}, {"speaker": "Aimee", "text": "Work days, you have to follow a routine, I guess because you have to get ready, you have to get out the door. But on days off, I just do what I feel like pretty much. Pretty relaxed."}, {"speaker": "Paul", "text": "Well, that I think is important isn't it, to relax on your days off. But like on a work day, so what do you do first in the morning?"}, {"speaker": "Aimee", "text": "I think probably what everybody does first. I have to go to the bathroom."}, {"speaker": "Paul", "text": "Okay. I mean, what do you do after that? Do you make yourself a hot drink?"}, {"speaker": "Aimee", "text": "I wash my face and brush teeth, pretty much, and then cajole my daughter into getting on with her morning routine as well, making sure she's ready."}, {"speaker": "Paul", "text": "I see. So you've got to get two people ready."}, {"speaker": "Aimee", "text": "Yes, I do. How about you?"}, {"speaker": "Paul", "text": "I just need to worry about myself really. I think that's enough, you know."}, {"speaker": "Aimee", "text": "Is that a big task?"}, {"speaker": "Paul", "text": "Yeah. Well, I always have a cup of tea in the morning. First thing, I always put the kettle on and make a hot drink. And I usually try to eat like a good breakfast, not just a piece of toast or something but maybe some eggs, scrambled eggs and maybe some bacon and some toast. Yeah, I try to leave the house with a full stomach."}, {"speaker": "Aimee", "text": "Yeah, that's good. I try to do that as well. Sometimes, we're pretty rushed and breakfast is sometimes eaten in the car. But we do get full stomachs eventually."}, {"speaker": "Paul", "text": "Right, right."}, {"speaker": "Aimee", "text": "Do you ever have fruit with your breakfast?"}, {"speaker": "Paul", "text": "I don't. I know some people eat like a grapefruit. Actually, occasionally, I have a banana."}, {"speaker": "Aimee", "text": "Hmm."}, {"speaker": "Paul", "text": "Yeah, because I just find it's really easy, and convenient, and quick."}, {"speaker": "Aimee", "text": "I agree."}, {"speaker": "Paul", "text": "But stuff like, you know, grapefruits and oranges, you have to peel them. Yeah, I just don't have the time really in the morning."}, {"speaker": "Aimee", "text": "Too much like hard work?"}, {"speaker": "Paul", "text": "Yeah. But if I stay in like if I'm on a holiday in a hotel and they have like a nice breakfast, I always try to eat fruit. So I always try to eat a bit of everything actually."}, {"speaker": "Aimee", "text": "When it's there in front of you, ready."}, {"speaker": "Paul", "text": "When it's made for you, yeah."}, {"speaker": "Aimee", "text": "I do that, too, definitely."}, {"speaker": "Paul", "text": "Yeah."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1331 | Intermediate (B1)", "originalTitle": "Morning Routine"}, {"id": "family-routine", "level": "b1", "source": "https://elllo.org/english/1301/T1332-amy-single-vs-married.htm", "audioSource": "https://elllo.org/Audio/A1301/1332-amy-single-vs-married.mp3", "audio": "audio/family-routine.mp3", "duration": 222.01, "waveform": [34, 42, 34, 28, 41, 36, 34, 24, 40, 27, 27, 35, 39, 34, 39, 24, 34, 34, 29, 29, 32, 25, 32, 26, 23, 31, 26, 31, 21, 27, 32, 29, 40, 28, 32, 23, 23, 43, 31, 34, 36, 48, 42, 38, 32, 30, 34, 33, 30, 31, 38, 27, 56, 56, 32, 30, 25, 30, 25, 27, 28, 40, 42, 50, 29, 36, 39, 27, 23, 34, 35, 35], "transcript": [{"speaker": "Paul", "text": "Hi, Aimee."}, {"speaker": "Aimee", "text": "Hi."}, {"speaker": "Paul", "text": "So we're talking about routines and in the evening, what's your usual routine?"}, {"speaker": "Aimee", "text": "Get home, wash hands, usually just try and get the dinner organized. Dinner and get my daughter ready for bed, usually. Just get her sorted before I think about relaxing or doing anything else, because if I sit down, I never want to stand back up again when I get from work."}, {"speaker": "Aimee", "text": "So yeah, my evening routine is usually pretty steady. Just get everybody fed, the youngest person washed into bed, and then I can relax. How about you?"}, {"speaker": "Paul", "text": "Yeah, I live alone, so I get back from work and I try to cook for myself. So most nights of the week, I'll probably go home and I then go to the supermarket, get some stuff to cook and cook dinner and then maybe relax in front of my computer, watch some TV and maybe do some work."}, {"speaker": "Paul", "text": "But maybe that's my routine for about five nights of the week. And then maybe, the other two nights, I'll go out with friends and go for dinner and maybe go for a few drinks."}, {"speaker": "Aimee", "text": "Sounds good."}, {"speaker": "Paul", "text": "Yeah."}, {"speaker": "Aimee", "text": "Yeah, I was thinking about my weekday routine. I guess, weekend routine is more relaxed. It's not as stuck, I guess. The weekend, yeah, we'd maybe go for dinner or go for a bath."}, {"speaker": "Paul", "text": "So Aimee, you sound, you know, very much into family life. Do you ever sort of miss being single?"}, {"speaker": "Aimee", "text": "My single life routine?"}, {"speaker": "Paul", "text": "Yeah."}, {"speaker": "Aimee", "text": "I think I sometimes miss the freedom and maybe the—especially the freedom with my finances, just being able to spend my money on myself, going out to concerts or nightclubs. Yeah, sometimes but not very much. I think what has replaced it is good for my current lifestyle. I think it suits me. I'm happy."}, {"speaker": "Paul", "text": "So you'd recommend family life to somebody like me who's single?"}, {"speaker": "Aimee", "text": "If you find the right family, I think yeah. Family life is good. It's fun. You'd find that families can stick with other families and the adults can still have a laugh and have adult conversation and the kids can play. If the kids are happy, then the parents are happy and you can still have a laugh and hopefully, not talk about too many childish things. You don't have to talk about changing nappies or anything—"}, {"speaker": "Paul", "text": "So you still have a social life then?"}, {"speaker": "Aimee", "text": "We try to, yes. We try to. Yeah, when budget allows and our daughter, she's five, so there's more freedom that comes when your children get older. When they're younger, then the rule a bit more unfortunately. But such as life. I would recommend it, Paul, yes."}, {"speaker": "Paul", "text": "Okay. I'll have to think seriously about it. Thanks, Aimee."}, {"speaker": "Aimee", "text": "You're welcome."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1322 | Intermediate (B1)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "mars", "level": "b1plus", "source": "https://elllo.org/english/1401/1432-JohnSarah-Mars.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1401-1450/1432-JohnSarah-Mars.mp3", "audio": "audio/mars.mp3", "duration": 248.08, "waveform": [50, 38, 35, 29, 33, 32, 24, 32, 34, 31, 33, 29, 20, 31, 31, 31, 34, 28, 35, 41, 42, 37, 44, 42, 43, 44, 41, 46, 38, 39, 32, 35, 37, 29, 29, 40, 37, 39, 37, 36, 29, 45, 39, 39, 38, 40, 50, 47, 35, 44, 33, 56, 34, 33, 27, 27, 30, 30, 35, 39, 42, 45, 40, 39, 48, 51, 40, 18, 26, 37, 40, 24], "transcript": [{"speaker": "Sarah", "text": "So do you think we should sent people to Mars or Moon to spend all this money on space travel?"}, {"speaker": "John", "text": "Well, I think we should. Space travel can give people hope for the future, and space travel can unite people from different countries for a common goal."}, {"speaker": "Sarah", "text": "But do any countries work together to travel in space?"}, {"speaker": "John", "text": "Oh certainly. The International Space station has astronauts from different countries working together. And I think that a joint effort is the best way to do space missions. I think that we could go back to the Moon and learn much more by going there than we can learn if we don't go there."}, {"speaker": "Sarah", "text": "I see what you mean, but I think we could learn more and we could improve more if we can help the people on Earth. Think of everything we could learn from the children that can't get an education these days. Maybe the next Einstein is a poor little girl who doesn't have the money to go to school. If we spent more money on school or clean water and vaccines, maybe we could learn more from ourselves than from going to space and going to Mars."}, {"speaker": "John", "text": "I agree with you that more should be spent on education, but we don't need the next Einstein if were not doing space travel. The problem is what are people with money willing to spend it on. I think that it would be nice if we could have all the rich countries spend money on education for poor people, but if you look at the numbers, the cost of one space mission is much cheaper than the things we spend money on now."}, {"speaker": "Sarah", "text": "Like what?"}, {"speaker": "John", "text": "Well, the first example that comes to mind is war. One day of war is so expensive for all the governments and the militaries that are involved. One day of war costs more money than one space mission. But war goes on and on for days."}, {"speaker": "Sarah", "text": "Yeah, and years."}, {"speaker": "John", "text": "So, if you think about money in terms of ... sorry ... so the money for a space mission is expensive by itself, but when you compare it to other things it's actually kind of cheap."}, {"speaker": "Sarah", "text": "I see what you're saying. You're comparing the cost of space travel to war, but I would compare the cost of space travel to the cost of, for example, getting rid of malaria. I think we could get rid of a terrible disease like malaria for as much as we would spend on a trip to Mars."}, {"speaker": "John", "text": "Getting rid of malaria or going to Mars? Well, of course I would also choose that we get rid of malaria."}, {"speaker": "Sarah", "text": "Maybe we'll have to agree to disagree."}, {"speaker": "John", "text": "We might have to disagree this time."}, {"speaker": "Sarah", "text": "OK."}], "speakerEvidence": ["Assets/speakers/US-Sarah2.jpg", "Assets/speakers/US-John.jpg", "Assets/flags/flag-usa.png", "Assets/flags/flag-usa.png"], "sourceLevelText": "Views #1432 | Intermediate (B1)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "music", "level": "b1plus", "source": "https://elllo.org/english/1401/1441-John-Sarah-Music.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1401-1450/1441-John-Sarah-Music.mp3", "audio": "audio/music.mp3", "duration": 185.81, "waveform": [41, 36, 47, 42, 42, 44, 38, 35, 32, 35, 36, 28, 34, 29, 43, 38, 29, 55, 39, 29, 32, 47, 47, 44, 44, 44, 34, 45, 43, 40, 30, 27, 31, 35, 38, 47, 49, 51, 47, 43, 39, 37, 40, 40, 34, 37, 36, 36, 35, 31, 42, 36, 35, 46, 50, 51, 29, 56, 46, 47, 45, 44, 45, 45, 31, 33, 35, 26, 32, 40, 35, 27], "transcript": [{"speaker": "John", "text": "So Sarah, do you play any musical instruments?"}, {"speaker": "Sarah", "text": "Yeah. I play two. I love to play the guitar. I started playing in college, and I like to play the piano, too. I started learning the piano when I was really young. How about you?"}, {"speaker": "John", "text": "Oh that's interesting. For me, I started playing the trumpet when I was really young, and I don't play it much anymore. But I started playing the piano when I finished high school, and I still play it now."}, {"speaker": "Sarah", "text": "Oh wow. So you started learning the piano when you were older."}, {"speaker": "John", "text": "Yes."}, {"speaker": "Sarah", "text": "Do you think people can start to learn an instrument at any age?"}, {"speaker": "John", "text": "Yes, I think so. Do you have a theory about that?"}, {"speaker": "Sarah", "text": "Yeah. I think that if people start to play an instrument when they're older, I think they enjoy it more because they chose to learn it. And I think they're going to play it longer. But if you have to learn an instrument when you're younger, I think you won't continue playing it."}, {"speaker": "John", "text": "Oh, because you have to practice for homework or something like that."}, {"speaker": "Sarah", "text": "Yeah. I have five brothers. And we all learned how to play the piano, but as soon as my brothers graduated from high school and went away, they stopped playing the piano. And they don't play it now. In fact, they forgot everything."}, {"speaker": "John", "text": "Oh, wow."}, {"speaker": "Sarah", "text": "Yeah."}, {"speaker": "John", "text": "Well, I do think that music education is very important for children because reading sheet music is like reading a language. And children can learn it much easier than adults learn. So no matter what instrument you play, if you're a child you learn how to read music."}, {"speaker": "Sarah", "text": "And I think too, it's really important for kids to be a part of a group like that. For example, singing in the choir or playing music in the orchestra, I think it's really good for kids to learn to work together and make music as a team. I have some really good memories about being a young kid in the orchestra."}, {"speaker": "John", "text": "Me too. I was also in choir and orchestra and marching band. So I don't play the orchestra instruments anymore and I don't play the marching band instruments anymore but I'm very glad that I had the experience of learning to read music and learning to work together as a team."}, {"speaker": "Sarah", "text": "That's true. Me too. Okay. I changed my mind. Even little kids, they should learn how to play a musical instrument."}], "speakerEvidence": ["Assets/speakers/US-Sarah2.jpg", "Assets/speakers/US-John.jpg", "Assets/flags/flag-usa.png", "Assets/flags/flag-usa.png"], "sourceLevelText": "Views #1441 | Intermediate (B1)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "house-rules", "level": "b1plus", "source": "https://elllo.org/english/1451/1460-Katie-RentHouse.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1451-1500/1460-Katie-RentHouse.mp3", "audio": "audio/house-rules.mp3", "duration": 181.11, "waveform": [46, 56, 35, 45, 54, 40, 39, 43, 38, 37, 36, 38, 30, 36, 35, 38, 43, 35, 36, 38, 34, 32, 42, 51, 46, 34, 44, 42, 34, 40, 35, 37, 35, 51, 35, 36, 32, 42, 37, 36, 37, 43, 31, 31, 30, 29, 31, 32, 37, 41, 42, 29, 24, 32, 44, 50, 42, 49, 46, 36, 51, 46, 37, 41, 40, 51, 43, 36, 36, 49, 36, 37], "transcript": [{"speaker": "Katie", "text": "Hey Todd, can I ask you a favor?"}, {"speaker": "Todd", "text": "Sure, anytime."}, {"speaker": "Katie", "text": "Um, I really need a place to stay, and I heard that your place is on AirBNB."}, {"speaker": "Todd", "text": "It is on AirBNB. I do rent my house, but for you it's free."}, {"speaker": "Katie", "text": "OH, amazing. Can I stay there then?"}, {"speaker": "Todd", "text": "You can. How long?"}, {"speaker": "Katie", "text": "Maybe a week or two weeks."}, {"speaker": "Todd", "text": "OK, when?"}, {"speaker": "Katie", "text": "From next Monday."}, {"speaker": "Todd", "text": "Yeah, actually, you can do that. That works."}, {"speaker": "Katie", "text": "Excellent. Thank you so much! How about a car? Can I park my car?"}, {"speaker": "Todd", "text": "Ah, that's a problem. You can't park your car because there's no space, but there's a cheap parking lot about maybe two blocks away."}, {"speaker": "Katie", "text": "OK."}, {"speaker": "Todd", "text": "So, it's only a couple dollars a day."}, {"speaker": "Katie", "text": "OK, I guess I can park my car there. How about cooking there? Can I cook?"}, {"speaker": "Todd", "text": "Of course, you can cook. I have a stove, a refrigerator. You can bring your own food. You can do whatever you want."}, {"speaker": "Katie", "text": "Excellent. Thank you. Can I use the Internet?"}, {"speaker": "Todd", "text": "You can use the Internet. There's a password. I will write down the password before I leave, and I will write down the password before you get there."}, {"speaker": "Katie", "text": "Excellent. Thank you so much! I was thinking about asking my friend if he can stay. Can my friend stay over?"}, {"speaker": "Todd", "text": "Yeah, sure, so your friend can stay. Not a problem I don't think."}, {"speaker": "Katie", "text": "He has a dog? Can he bring his dog?"}, {"speaker": "Todd", "text": "Oh, that is a problem. Does the dog have a cage?"}, {"speaker": "Katie", "text": "Ah, no, but we can get a cage."}, {"speaker": "Todd", "text": "I'm not sure about the dog. If the dog is in a cage, it's OK in the house but I think you can't have the dog in the house."}, {"speaker": "Katie", "text": "OK, how about smoking? My friend is a very heavy smoker. Can he smoke outside?"}, {"speaker": "Todd", "text": "Yeah, he can smoke outside, just please pick up cigarette butts, but of course, he can't smoke inside."}, {"speaker": "Katie", "text": "OK, he can't smoke inside."}, {"speaker": "Todd", "text": "No."}, {"speaker": "Katie", "text": "OK, how about if we want to have a party? Can we have a party?"}, {"speaker": "Todd", "text": "Yeah, you can have a party. That's OK, but please be quiet. Don't be too loud. The neighbors live very close to my house."}, {"speaker": "Katie", "text": "Alright, that sounds good. Thanks. And I have one more question. Can I use the washing machine?"}, {"speaker": "Todd", "text": "Yeah, of course. You can use anything. You use the washing machine. You can use the Internet. You can use the TV. You can use anything you like."}, {"speaker": "Katie", "text": "Wow, excellent. That sounds great. Thank you so much."}, {"speaker": "Todd", "text": "Yeah, I will write down directions for my house, and I will send you a map, and you can check it out and get all the information, and just I will leave the key for you with my neighbor."}, {"speaker": "Katie", "text": "Excellent. Thank you very much!"}, {"speaker": "Todd", "text": "Sure, no problem."}], "speakerEvidence": ["Assets/speakers/UK-Katie.png", "Assets/speakers/US-Todd.jpg", "Assets/flags/flag-england.png", "Assets/flags/flag-usa.png"], "sourceLevelText": "Views #1460 | Beginner (A2)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "unplugged", "level": "b1plus", "source": "https://elllo.org/english/1301/T1342-paul-unplugged.htm", "audioSource": "https://elllo.org/Audio/A1301/1342-paul-unplugged.mp3", "audio": "audio/unplugged.mp3", "duration": 230.87, "waveform": [26, 35, 26, 32, 27, 28, 30, 33, 34, 24, 32, 34, 43, 32, 29, 31, 28, 35, 48, 45, 32, 37, 37, 33, 39, 37, 32, 32, 29, 30, 31, 52, 37, 35, 40, 36, 29, 32, 24, 34, 36, 33, 49, 28, 33, 38, 32, 26, 25, 24, 25, 37, 36, 31, 29, 31, 29, 26, 30, 30, 56, 37, 34, 31, 35, 23, 28, 21, 27, 31, 20, 24], "transcript": [{"speaker": "Aimee", "text": "So Paul, speaking of technology, how long do you think you can go without checking your phone?"}, {"speaker": "Paul", "text": "Ah, it’s quite embarrassing, really, if I’m honest, I check it a lot. I really do, like I’m always having to look at Facebook, my emails. I’m looking at the football news online… yeah, I mean ….It’s not something that I’m proud about; but it’s something that, yeah, it’s quite a big part of my life, I think."}, {"speaker": "Aimee", "text": "If you left the house and you had forgotten your phone, would you feel something really missing?"}, {"speaker": "Paul", "text": "I did actually I forgot my…I use my iPad a lot, and I forgot my iPad the other day just as I was leaving, and my bus was about to arrive. And I really had the strong like pull to get back for it. But I caught myself and decided that yeah, I can manage without it, you know, for one day."}, {"speaker": "Aimee", "text": "Could you manage?"}, {"speaker": "Paul", "text": "Yeah, I did, I didn’t even think about it actually. It was just that you know, that sort of momentary pull where I thought I needed it, and then actually having you know, sort of considered it seriously. It was like, I don’t need it, so yeah, I did find without it I didn’t have to be like hooked up to a life support system or anything. Yeah, it’s amazing really, how it comes to be such a central part in your life. How long do you think you could go without using the internet?"}, {"speaker": "Aimee", "text": "Ahh, I check my phone thousands of times a day… To exaggerate, did I say thousands? I check it too much, I think, far too much. If I left my home, I would feel gutted. I would feel like I’m really, really missing something. It would definitely be a big, big pull, I think. I read a lot of things on the internet and I check things and, and yeah. When it’s not there, then I do feel like something is maybe I should be doing something, or missing out on something. And it’s not good - I’m embarrassed it’s not good at all. So I think I need to work on unplugging."}, {"speaker": "Paul", "text": "I’ve heard a lot of people they try to do at least one or two days a week when they don’t use the internet at all. But that sounds like it could be quite a good idea. You know, maybe just you know, unplug."}, {"speaker": "Aimee", "text": "Yeah. Do you think you could?"}, {"speaker": "Paul", "text": "I think I could, yeah, I think I could. In fact, I really like hiking and being outdoors, and, I think one of the things I really love about it is that I’m … nobody can contact me, you know? And I’m kinda away from everything. And I really enjoy those moments."}, {"speaker": "Aimee", "text": "Uhm, yeah. I don’t know if I could. I always have to cut down before going cold turkey, I think, I’ve got to cut down. I’m trying to cut down. You know, I mentioned before, I’m trying to get back into reading uhm, just get back into real books instead of screen time. So, yeah, I couldn’t go cold turkey, I think, a couple of days a week. I would need to cut down."}, {"speaker": "Paul", "text": "Yeah, yeah, yeah, I think we should probably yeah, make a concerted effort I think it is probably good for us to try to reduce our, you know, user time."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1342 | Intermediate (B2)", "originalTitle": "Dialed In vs Unplugged"}, {"id": "email", "level": "b2", "source": "https://elllo.org/english/1301/T1341-amy-email-habits.htm", "audioSource": "https://elllo.org/Audio/A1301/1341-amy-email-habits.mp3", "audio": "audio/email.mp3", "duration": 143.91, "waveform": [47, 44, 37, 48, 37, 43, 35, 32, 36, 36, 31, 36, 34, 30, 35, 34, 39, 34, 32, 47, 56, 46, 31, 30, 49, 54, 31, 31, 22, 48, 46, 34, 41, 43, 43, 46, 36, 33, 47, 33, 29, 35, 36, 34, 32, 32, 33, 29, 26, 31, 37, 32, 30, 32, 32, 28, 29, 34, 30, 26, 38, 29, 44, 34, 29, 45, 40, 49, 52, 40, 26, 23], "transcript": [{"speaker": "Paul", "text": "So Aimee, do you always check your emails in the morning?"}, {"speaker": "Aimee", "text": "Probably. Probably. Recently, I’m trying to stop using my electronic devices so much. So I think in the morning, I need to do other things but very often, I will quickly scan my phone and check because my phone is also my alarm clock, so it’s right there. It’s too handy."}, {"speaker": "Paul", "text": "Yeah. I’m always one that wake up—I don’t know, I’ve got this really bad habit where I think something major has happened during the night. And so I wake up and I’m checking different websites and checking Facebook to see if there’s any messages or any great news over the course of the night."}, {"speaker": "Paul", "text": "Yeah, it’s a really bad habit, you know. It starts to kind of dominate your life. Yeah, I think it’s quite addictive things, isn’t it?"}, {"speaker": "Aimee", "text": "Yeah. I’ve been thinking about it a lot recently. And it’s something I think that doesn’t need to be in the morning routine so much. It’s good to just get your head ready before you—your head and your body ready before you start thinking about checking emails and stuff."}, {"speaker": "Paul", "text": "I agree. I heard somebody—there was a piece of advice, I can’t remember where I heard it from. But it was just to check your emails twice a day. You know, you don’t need to do more than that. Check once in the morning, once in the evening, that’s it. Check your news websites, maybe twice a day rather than every 30 minutes or something."}, {"speaker": "Aimee", "text": "Yeah, that’s—"}, {"speaker": "Paul", "text": "Yeah. I think it requires discipline doesn’t it?"}, {"speaker": "Aimee", "text": "It does."}, {"speaker": "Paul", "text": "Yeah."}, {"speaker": "Aimee", "text": "It’s good advice but I don’t know if it’s very practical because if you’re using a smartphone, which I do, then you’re using it first, it’s got so many different function and you need it for—need it, I guess is a loose term. But you use it for so many different things. So it’s always there, you know. Always there."}, {"speaker": "Aimee", "text": "However, I did start reading a book the other day, so I’m trying to stop looking at my phone and start reading a book instead."}, {"speaker": "Paul", "text": "Oh, good for you. Yeah."}, {"speaker": "Aimee", "text": "Thanks."}, {"speaker": "Paul", "text": "That’s good move. Yeah, I should perhaps do that myself."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1341 | Intermediate (B2)", "originalTitle": "E-Mail Habits"}, {"id": "climate", "level": "b2plus", "source": "https://elllo.org/english/1301/T1301-amy-climate-change.htm", "audioSource": "https://elllo.org/Audio/A1301/1301-amy-climate-change.mp3", "audio": "audio/climate.mp3", "duration": 178.55, "waveform": [38, 36, 34, 32, 56, 28, 32, 39, 36, 32, 34, 39, 31, 30, 36, 28, 26, 37, 28, 27, 32, 41, 36, 28, 23, 36, 33, 39, 29, 36, 32, 30, 25, 33, 28, 25, 29, 32, 27, 34, 31, 33, 46, 39, 20, 33, 33, 32, 38, 35, 30, 32, 26, 29, 33, 34, 30, 24, 30, 30, 28, 28, 34, 24, 26, 28, 28, 25, 40, 27, 25, 32], "transcript": [{"speaker": "Paul", "text": "So have you seen all these freakish weather events on the news all around the world?"}, {"speaker": "Aimee", "text": "Yeah, yeah. I'm trying to pay attention, yeah. It's been pretty bad in some places. I think, it's been the wettest January on record in the UK at the moment."}, {"speaker": "Paul", "text": "Right, right, right. So do you think it's kind of indicative of climate change? Are you a climate change believer or a climate change denier?"}, {"speaker": "Aimee", "text": "I think it's hard to deny really. I think what humans do to the planet is going to have some effect and science is science, you know. It's backed up by evidence and facts and scientists don't tend to say things until they know it's true or as true as it can be. So yeah, I'm definitely a believer in climate change, I think. We are affecting things on the planet."}, {"speaker": "Aimee", "text": "How about you?"}, {"speaker": "Paul", "text": "I've read quite a lot about it. And yes, there is a science to support it but there's also a lot of science to — not to deny it but there's definitely a lot of questions that aren't answered yet. It's a very sort of complex issue. I mean, these global systems of weather and you've got all these like organic processes going on that we just don't really understand. And then trying to explain all these complex events by saying it's climate change, it's…"}, {"speaker": "Paul", "text": "I mean, what worries me is that by denying it, it seems to also be a sort of justification for us to continue living the way we are, which worries me a lot. Whether it's true or not, I think we need to be thinking about how we can live better. And that means, living in ways that are less, sort of, damaging on our environment."}, {"speaker": "Aimee", "text": "Yeah, I agree. I agree. I've also read a bit about weather systems that are perhaps not—because of climate of change, every planet has weather systems that come and go. And I understand that part but I also fully agree that we have to stop being so destructive."}, {"speaker": "Aimee", "text": "I think it's pretty clear. You can't continue cutting down acres and acres and acres of really valuable resources like the rainforest. I mean, we need that to breathe, so it just doesn't make sense. Yeah, I think we definitely have to stop being so destructive."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1301 | Advanced (C1)", "originalTitle": "Climate Change"}, {"id": "media", "level": "b2", "source": "https://elllo.org/english/1451/1470-MegTodd-CompareMedia.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1451-1500/1470-MegTodd-CompareMedia.mp3", "audio": "audio/media.mp3", "duration": 298.08, "waveform": [34, 35, 35, 40, 32, 39, 33, 37, 35, 36, 38, 33, 33, 34, 46, 52, 40, 38, 41, 39, 44, 34, 46, 54, 56, 41, 44, 48, 42, 36, 43, 40, 37, 40, 42, 43, 31, 34, 31, 34, 35, 34, 29, 41, 36, 38, 42, 43, 36, 37, 35, 32, 29, 40, 34, 34, 39, 41, 33, 32, 32, 28, 37, 35, 27, 36, 36, 32, 34, 27, 26, 8], "transcript": [{"speaker": "Meg", "text": "Hey Todd, so continuing talking about then and now, I was thinking we could switch to talking about just life in general."}, {"speaker": "Todd", "text": "Sounds good."}, {"speaker": "Meg", "text": "So my first question for you is are movies today more interesting than before?"}, {"speaker": "Todd", "text": "Well. I'm gonna sound like an old guy, but I would say no, movies are not more interesting today. Movies were much better, twenty, thirty years ago. The stories were better. They were more interesting. These days movies just have too much special effects, and there's too many movies about superheroes. I hate movies about superheroes. So yeah, I think movies used to be more interesting. What do you think?"}, {"speaker": "Meg", "text": "I have the opposite opinion of you. I think movies today are more interesting than before. Maybe I'm too used to a lot of special effects, so when I watch some older movies, the story might be interesting, but I get a little bored watching it and actually I love superhero movies."}, {"speaker": "Todd", "text": "Oh really?"}, {"speaker": "Meg", "text": "So I would say that yes, any superhero movies - Spider man or Batman especially is my favorite so those movies for me are more interesting than in the past."}, {"speaker": "Todd", "text": "OK, well we're talking about comparatives, so who's cooler Batman or Spider-Man?"}, {"speaker": "Meg", "text": "Oh, Batman. Hands down."}, {"speaker": "Todd", "text": "I'm sorry. I think Spider-Man's really lame. I've never liked Spider-Man"}, {"speaker": "Meg", "text": "He kind of whines a lot."}, {"speaker": "Todd", "text": "He looks like a kid in his pajamas."}, {"speaker": "Meg", "text": "He is a kid in his pajamas."}, {"speaker": "Todd", "text": "Maybe that's it."}, {"speaker": "Meg", "text": "Whereas Batman has a lot of skills that he's developed himself, so."}, {"speaker": "Todd", "text": "True, true. OK, well how about Batman, so like who is better?"}, {"speaker": "Meg", "text": "Who is the best Batman?"}, {"speaker": "Todd", "text": "Yeah, so who is better? Who was the last one? It was ..."}, {"speaker": "Meg", "text": "Well, the most recent Batman was Ben Affleck, but I didn't watch that one"}, {"speaker": "Todd", "text": "OK."}, {"speaker": "Meg", "text": "So before that, there was Christian Bale"}, {"speaker": "Todd", "text": "Oh, that's right."}, {"speaker": "Meg", "text": "So without having seen Ben Affleck, I would still say that Christian Bale was a better Batman."}, {"speaker": "Todd", "text": "Yeah, I'm sure. I'm sure. OK, so let's talk about other things. How about the news? With news are you more knowledgeable these days than before, say five ten years ago?"}, {"speaker": "Meg", "text": "Actually, I think I am less knowledgeable than before. There's a lot of news out there, and it's easy to access the news but there's so much news coming from so many sources, I'm now sure which news service is more trustworthy, so I think it's more difficult now to find the correct news. The true news. What do you think?"}, {"speaker": "Todd", "text": "I agree. Sadly I think I am less knowledgeable because before I would read the newspaper, or I would read magazine articles or I would listen to better news stories on the news. These days I just look at a Facebook headline and I don't even read the article, so I don't even know what's going on sometimes. Which is terrible for a man my age."}, {"speaker": "Meg", "text": "Terrible for anyone I think."}, {"speaker": "Todd", "text": "Yeah, I think it's because I think the news was more honest than before, than now, sorry. I think the news is less honest these days. It used to be more honest. I just don't trust the news anymore."}, {"speaker": "Meg", "text": "Yeah, I don't really trust it either."}, {"speaker": "Todd", "text": "Yeah, less trustworthy."}, {"speaker": "Meg", "text": "So along those lines, would you say social media makes like better or worse for people?"}, {"speaker": "Todd", "text": "I think it's both, like I think it's you know, three points better, two points worse, so it's a negative. It's better because you can keep track of so many family members, especially if you're far away, so I like how it connects people, yeah, it just makes people sad sometimes, or makes them frustrated about their life maybe, so yeah, I don't think it makes life better. But I'm an old guy, so..."}, {"speaker": "Meg", "text": "Yeah, I think it's true. I think there are scientific studies to show that because of social media, people compare themselves too much so it's quite appropriate that we are talking about comparison because people will see other people's lives on social media that look quite good and they will compare themselves and feel bad about themselves, o for some people I think it has made it worse, but like you, I agree that some points are better like seeing pictures from my family."}, {"speaker": "Todd", "text": "Yeah, so true."}], "speakerEvidence": ["Assets/speakers/US-Meg.png", "Assets/speakers/US-Todd.jpg", "Assets/flags/flag-usa.png", "Assets/flags/flag-usa.png"], "sourceLevelText": "Views #1470 |  Intermediate (B2)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "kids-phones", "level": "b2", "source": "https://elllo.org/english/1401/1448-Katie-Phone.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1401-1450/1448-Katie-Phone.mp3", "audio": "audio/kids-phones.mp3", "duration": 165.02, "waveform": [49, 42, 56, 33, 35, 30, 26, 26, 29, 26, 28, 31, 34, 33, 31, 35, 21, 39, 43, 30, 41, 33, 36, 23, 30, 37, 22, 28, 56, 30, 27, 25, 24, 44, 30, 24, 31, 25, 26, 37, 24, 25, 30, 18, 34, 35, 22, 32, 29, 23, 28, 26, 33, 40, 52, 42, 49, 40, 30, 25, 20, 24, 41, 32, 22, 22, 35, 22, 38, 40, 40, 41], "transcript": [{"speaker": "Katie", "text": "So I want to ask you about when is the right age to have stuff or to start doing stuff. What do you think is the right age to start having a phone?"}, {"speaker": "Aimee", "text": "Oh, I think for security reasons, to, you know, keep the child safe, perhaps maybe about 11 or 12 when they start going around places without their parents."}, {"speaker": "Katie", "text": "Yeah."}, {"speaker": "Aimee", "text": "It would be a way for me to contact my daughter. Even now, my daughter is only six and she doesn't have a phone, and that's far too young, I believe. However, she walks to school by herself and walks home by herself. And that stresses me out for her safety."}, {"speaker": "Aimee", "text": "So there are times where I wish I could phone her or text her, but she doesn't have a phone. And I do believe that six is far too young to have a phone."}, {"speaker": "Katie", "text": "A little bit too young."}, {"speaker": "Aimee", "text": "Yes. So purely for security reasons, I think probably around 11 or 12."}, {"speaker": "Katie", "text": "How old were you when you first got your phone."}, {"speaker": "Aimee", "text": "Well, I'm an old person so, you know, people didn't have mobile phones. I was reaching the end of high school. I was, I think, 17 when I got my first mobile phone. And it was a big brick. But again, that was for, you know, I guess security reasons."}, {"speaker": "Katie", "text": "Yeah."}, {"speaker": "Aimee", "text": "My parents got it for me. I was going out, you know, I started going out at night, going to concerts. And I was beginning to be allowed going into bars and things at 17, 18. So yeah, it was a good security thing. My parents were appreciative of being able to contact me."}, {"speaker": "Katie", "text": "Yeah."}, {"speaker": "Aimee", "text": "How about you? How old were you when you first got your mobile phone?"}, {"speaker": "Katie", "text": "Oh goodness. I was about 12 or 13. I was really young."}, {"speaker": "Aimee", "text": "Okay."}, {"speaker": "Katie", "text": "And I only got my first mobile phone or my first cellphone because my best friend who got the same one and I wanted to send like picture messages to her. It was back in the old days where you can send a photo, you can take photos."}, {"speaker": "Aimee", "text": "Picture messages."}, {"speaker": "Katie", "text": "Picture messages."}, {"speaker": "Aimee", "text": "I couldn't even send picture messages. Mine was just texts, like pressing the same button over and over again."}, {"speaker": "Katie", "text": "Oh yeah. Oh yeah. So I never really used it as like a way of security. I just used it to send really overpriced picture messages to my friend for absolutely no reason. It was such a waste. And to play Snake. Do you remember Snake?"}, {"speaker": "Aimee", "text": "Oh yeah, Snake."}, {"speaker": "Katie", "text": "Like the little game that you could play on your phone."}, {"speaker": "Aimee", "text": "Yup, yup."}, {"speaker": "Katie", "text": "Yeah. I didn't use it for a good use, I think. I just used it to waste time."}, {"speaker": "Aimee", "text": "Fair enough. Well, you're 12, you said, right?"}, {"speaker": "Katie", "text": "Twelve, thirteen, yeah."}, {"speaker": "Aimee", "text": "That sounds age appropriate, I think, age appropriate use."}, {"speaker": "Katie", "text": "Yeah. It's a good time to start wasting your time."}, {"speaker": "Aimee", "text": "Yeah."}, {"speaker": "Katie", "text": "Get ahead to start wasting time."}, {"speaker": "Aimee", "text": "Yeah."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Katie.png", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1448 | Intermediate (B1)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "tropics", "level": "b2", "source": "https://elllo.org/english/1301/T1349-paul-tropics.htm", "audioSource": "https://elllo.org/Audio/A1301/1349-paul-tropics-job.mp3", "audio": "audio/tropics.mp3", "duration": 232.44, "waveform": [39, 44, 35, 45, 35, 30, 32, 30, 31, 32, 28, 28, 56, 32, 35, 37, 48, 42, 32, 35, 40, 33, 38, 40, 34, 32, 35, 34, 42, 33, 32, 29, 27, 32, 28, 37, 47, 45, 44, 54, 43, 34, 33, 41, 42, 39, 40, 45, 40, 47, 36, 43, 53, 35, 26, 45, 32, 31, 45, 40, 31, 33, 32, 35, 29, 39, 42, 39, 43, 35, 35, 23], "transcript": [{"speaker": "Aimee", "text": "So Paul, what’s the most memorable job experience that you have?"}, {"speaker": "Paul", "text": "Hmm, well, I think the most memorable one is the volunteering time that I spent in Australia. And I was up in the northeastern corner where there’s a relatively small rainforest's. And I was helping with a research station that’s located in the rainforest. So we do a range of different things, going from trying to control coconuts—coconut trees."}, {"speaker": "Aimee", "text": "Control?"}, {"speaker": "Paul", "text": "Yeah, because, like, believe it or not, you imagine this kind of tropical paradises to have coconut trees but they’re actually very invasive and they’re not native to that area. And basically, if you let a population of coconut trees to go out of control, nothing else can grow."}, {"speaker": "Aimee", "text": "Oh."}, {"speaker": "Aimee", "text": "They drop their fronds, and they drop, obviously, the coconuts, and nothing else can grow. So you basically lose a lot of the native species there. So we’re trying to keep them under control. There was also caring for bats that had been orphaned."}, {"speaker": "Aimee", "text": "Bats?"}, {"speaker": "Paul", "text": "Sometimes they’re born with physical disabilities that mean they can’t survive in the wild."}, {"speaker": "Aimee", "text": "Like a sanctuary then."}, {"speaker": "Paul", "text": "Yes. Just like a sanctuary, yeah. So they take care of—"}, {"speaker": "Aimee", "text": "What size of bats, like any other—"}, {"speaker": "Paul", "text": "Fruit bats."}, {"speaker": "Aimee", "text": "What size are they?"}, {"speaker": "Paul", "text": "They’re pretty, like, once they spread—they’re like little monkeys with big wings."}, {"speaker": "Aimee", "text": "Yeah. So what’s their wing span then?"}, {"speaker": "Paul", "text": "Let’s say, maybe, I guess up to probably 4 feet. Does that sound too much?"}, {"speaker": "Aimee", "text": "So about a meter?"}, {"speaker": "Paul", "text": "Yeah. Some of the big dudes, they got huge wingspan."}, {"speaker": "Aimee", "text": "Oh, the only bats I’ve seen in real life are really tiny. They’re just like mice."}, {"speaker": "Paul", "text": "Oh, the micro-bats."}, {"speaker": "Aimee", "text": "They’re like little birds, you know. You see them flying around and you think, “Oh that’s birds.” No, they’re bats. So these guys sound pretty big."}, {"speaker": "Paul", "text": "Hmm, but they’re completely like omnivorous. They only eat fruit, so like, they really—"}, {"speaker": "Aimee", "text": "Do they eat the coconuts?"}, {"speaker": "Paul", "text": "Well, the coconuts are kind of tough for them to get into. You need to be able to make a hole, I suppose, to get that."}, {"speaker": "Aimee", "text": "Of course, yeah."}, {"speaker": "Paul", "text": "But they eat all, mostly like fleshy fruits; apples or whatever they can get really—berries. They’re really important for spreading—because obviously they eat the flesh of the fruit but they don’t eat the seeds. So they just kind of pass through them and they’re really useful for dispersing seeds. So rainforest regeneration, they’re very important animals."}, {"speaker": "Aimee", "text": "So they’re like the big bumble bees of the rain forest, then."}, {"speaker": "Paul", "text": "Yeah. I guess you could look at it like that, yeah. So yeah, that was an interesting volunteering kind of odd job that I had, I suppose."}, {"speaker": "Aimee", "text": "Yeah. Essentially yet really cool."}, {"speaker": "Paul", "text": "I really like to go back there someday."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1349 | Intermediate (B2)", "originalTitle": "In the Tropics"}, {"id": "black-friday", "level": "b2plus", "source": "https://elllo.org/english/1451/1471-Aimee-BlackFriday.htm", "audioSource": "https://elllo.org/act/3X3PGQ/1471-Aimee-Black-Friday.zip", "audio": "audio/black-friday.mp3", "duration": 265.44, "waveform": [41, 49, 46, 50, 50, 45, 43, 45, 44, 31, 43, 41, 46, 46, 47, 41, 56, 44, 40, 51, 43, 42, 52, 46, 51, 40, 53, 47, 52, 48, 44, 49, 46, 34, 40, 44, 39, 39, 38, 43, 41, 38, 36, 37, 46, 40, 40, 48, 37, 42, 38, 34, 46, 43, 38, 35, 43, 45, 36, 41, 40, 36, 36, 48, 33, 39, 39, 36, 39, 42, 42, 32], "transcript": [{"speaker": "Aimee", "text": "OK, so hey Todd, so I have a question. I've noticed recently in the U.K. that this holiday called Black Friday has appeared, and this is a new thing for us. I don't really know why it has appeared. I think it is American. Shops just give super discounts in November and people are going crazy for like TVs and stuff. Do you have experience with this?"}, {"speaker": "Todd", "text": "Yeah, unfortunately, I think it is one of our worst exports. Like I am not a fan of Black Friday. We've had it now probably for like ten or twenty years. I can't remember but it started where the department stores would have these massive sales on Friday which is the day after Thanksgiving, which is always on a Thursday in November."}, {"speaker": "Aimee", "text": "Ah, that's the connection. OK, after Thanksgiving."}, {"speaker": "Todd", "text": "Right, and I think it was called Black Friday because that was the day that the stores could show that they had a profit for the year, or something like that."}, {"speaker": "Aimee", "text": "OK, so it's blatantly all about money?"}, {"speaker": "Todd", "text": "Oh, totally and originally, what they would do is they would entice people with really good bargains, but then they kept ratcheting up the bargain, so now they have these really, really low teaser products, like they only offer ten TVs or something like that for like twenty bucks."}, {"speaker": "Aimee", "text": "Oh, so it's like a limited, a really limited supply of really good deals?"}, {"speaker": "Todd", "text": "Yeah, and so then what you do is you get these huge crowds that converge on these stores, and then they open the doors and people rush in and literally it's a free-for-all. You have fights and it's so crazy."}, {"speaker": "Aimee", "text": "I've seen that. I've seen videos and clips, and it started happening in the U.K. now"}, {"speaker": "Todd", "text": "Oh, no!"}, {"speaker": "Aimee", "text": "And I can't believe it that people can be so greedy."}, {"speaker": "Todd", "text": "And especially what's bothersome is that you're with your family on a holiday. You're having a good time, and then you go to war practically. You know what I mean?"}, {"speaker": "Aimee", "text": "Yeah, with strangers"}, {"speaker": "Todd", "text": "Yeah."}, {"speaker": "Aimee", "text": "Or your neighbor even. It doesn't matter who it is, just fighting over a cheap TV."}, {"speaker": "Todd", "text": "I mean, I'm proud to say I've never been to a Black Friday."}, {"speaker": "Aimee", "text": "Me neither. Me neither."}, {"speaker": "Todd", "text": "So I guess that's hypocritical for me to say that because you know, since I've never been to a Black Friday. I've only seen it, but I just don't like going to shopping malls and to, like, department stores very much - big box stores. I'm just not a shopper."}, {"speaker": "Aimee", "text": "So you prefer online shopping?"}, {"speaker": "Todd", "text": "I just prefer not shopping at all. Like I don't care like what I dress or how I dress. So, like, I buy my clothes at a supermarket. You know. I know, I'm not the most fashionable person, but as for Black Friday, you know, I think a lot of times, parents what to get stuff for their kids, you know, they want to get that special gift. Maybe I think that's what attracts a lot of the crowds."}, {"speaker": "Aimee", "text": "Yeah, it is, you know, once Thanksgiving is over then it's the build-up to Christmas, so of course there's the stress of preparing everything in time for that. It's hard to resist really good bargains, I guess if you're trying to be careful with your money. You're trying to be sensible or there's those gifts that, you know your child really wants, so I can understand people feel a lot of pressure to do that."}, {"speaker": "Todd", "text": "I mean, some of the stores, look like they've been through a hurricane after the crowds go through it. It's crazy."}, {"speaker": "Aimee", "text": "It does sound awful. Doesn't sound like my idea of a good time."}, {"speaker": "Todd", "text": "No. Now there is one option though if you don't want to face the crowds and all the hysteria, you can do what's called Cyber Monday."}, {"speaker": "Aimee", "text": "OK."}, {"speaker": "Todd", "text": "Do you have Cyber Monday?"}, {"speaker": "Aimee", "text": "No, I'm not familiar with it."}, {"speaker": "Todd", "text": "So Cyber Monday - I think it's the Monday after Black Friday - and you just get all the deals online over a 24 hour period."}, {"speaker": "Aimee", "text": "OK, is like this remainder, leftover stock? Or is this like a new ...?"}, {"speaker": "Todd", "text": "No, this is just the online stuff, so I think it's just, you know, the Amazons and all the online stores, that they want to have their deals that people can buy."}, {"speaker": "Aimee", "text": "They wanted a piece of the action, basically."}, {"speaker": "Todd", "text": "Yeah, yeah. Exactly so they can make it super, super ..."}, {"speaker": "Aimee", "text": "It's too much!"}, {"speaker": "Todd", "text": "Yeah."}, {"speaker": "Aimee", "text": "It is all too much."}, {"speaker": "Todd", "text": "I know, we should have like a, you know, I don't know, a cut back on spending. But if you cut back on spending, then you're hurting the economy, right, so ..."}, {"speaker": "Aimee", "text": "I know. It's true."}, {"speaker": "Todd", "text": "Yeah!"}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/US-Todd.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-usa.png"], "sourceLevelText": "Views #1471  |  Intermediate (B2)", "originalTitle": "Get More Lessons Here &gt;&gt;"}, {"id": "club-job", "level": "b2plus", "source": "https://elllo.org/english/1301/T1350-amy-money-floor.htm", "audioSource": "https://elllo.org/Audio/A1301/1350-amy-money-on-floor.mp3", "audio": "audio/club-job.mp3", "duration": 256.57, "waveform": [37, 41, 44, 42, 51, 33, 21, 33, 46, 22, 27, 27, 27, 31, 36, 26, 29, 26, 33, 30, 32, 30, 27, 28, 27, 27, 26, 29, 26, 34, 26, 29, 33, 34, 31, 34, 50, 32, 22, 50, 33, 31, 27, 25, 26, 27, 33, 39, 29, 33, 35, 32, 24, 33, 46, 34, 26, 30, 31, 29, 26, 25, 31, 26, 25, 24, 25, 26, 32, 56, 43, 43], "transcript": [{"speaker": "Amy", "text": "I don't know how odd they were. I don't know. When I was in university, part time jobs, I used to work in restaurants and—the usual stuff—restaurants, and I think my favorite was working in a nightclub. It was a really, really big nightclub and I used to work on the floor, just kind of cleaning up, looking after all the drunk patrons."}, {"speaker": "Amy", "text": "And my first night there was—actually, one of my favorite DJs was on, so that was great. I got to listen to really good music whilst finding money on the floor, and cleaning up after folks. It was really good."}, {"speaker": "Paul", "text": "You found some money on the floor."}, {"speaker": "Amy", "text": "Yeah. You know, it was a busy club. Really, really full, a good couple of thousand people in there. And I guess people were doing whatever they were doing and they would drop big wads of cash. And because I was the person to clean up all the glass bottles, then I would find the wads of cash on the floor. So it was good. I’d get my wages, I’d get tips, and then I would get my own personal tips from finding money on the floor."}, {"speaker": "Paul", "text": "So you must have found like a whole range of different things, like, what else did you find?"}, {"speaker": "Amy", "text": "Yeah. A little wraps of things, and then packets of things, yeah. I mean, I had to work hard for the money. It wasn’t easy because the place was full, absolutely rammed of people. Everybody is incredibly drunk or whatever and they all just want to dance and have a good time. And I have to make sure there’s no broken glass for safety reasons, obviously. So I’m pushing my way through the crowd and keeping eyes on the floor constantly with a torch. And alongside the broken glass that I would sweep up would be, yeah, wads of cash, sometimes little purses, little bags, things like that."}, {"speaker": "Amy", "text": "When I find, like, identification for things—when it was a purse, I would do the right thing with it, hand it in but it was just a wad up, like a rolled up set of notes, I would just put them in my pocket for me, basically."}, {"speaker": "Paul", "text": "Yeah, it’s difficult to know what to do with cash because you’re handing it to someone who—well, it’s cash, isn’t it?"}, {"speaker": "Amy", "text": "I know."}, {"speaker": "Paul", "text": "Yeah, yeah."}, {"speaker": "Amy", "text": "I remember finding some driving license and student ID, and I took—it was actually the same university that I went to at the time, and I just took it to uni when I was going during the week. And I handed it in to make sure that it got back to the owner because you know that’s the worst thing about when you lose your purse or your wallet. The cash, you can kind of just say goodbye to. It’s a given really that it’s going to be gone, but it’s your ID and your cards and everything. It’s such a hassle trying to get them back again. So I wanted to make sure that whoever drunken idiot dropped them in that club that it got back to their hands safely."}, {"speaker": "Paul", "text": "Well, that’s nice. So you’re a thief with heart then."}, {"speaker": "Amy", "text": "I’m not a thief. I’m an opportunist."}, {"speaker": "Paul", "text": "I’m kidding. I’m kidding."}, {"speaker": "Amy", "text": "It’s on the floor."}, {"speaker": "Paul", "text": "I’m pulling your leg, Amy. No, I would have done the same."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Paul.jpg", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1450 | Intermediate (B2)", "originalTitle": "In the Club"}, {"id": "makeup", "level": "b2plus", "source": "https://elllo.org/english/1401/1447-Katie-MakeUp.htm", "audioSource": "https://s3-us-west-1.amazonaws.com/elllo-audio/views-1401-1450/1447-Katie-MakeUp.mp3", "audio": "audio/makeup.mp3", "duration": 293.83, "waveform": [51, 35, 34, 39, 35, 42, 41, 34, 35, 33, 35, 35, 35, 38, 37, 38, 39, 36, 39, 37, 37, 36, 30, 41, 37, 41, 35, 39, 38, 35, 35, 48, 33, 43, 41, 35, 34, 33, 39, 46, 34, 34, 31, 56, 45, 36, 38, 45, 37, 45, 40, 40, 40, 47, 42, 44, 34, 33, 39, 36, 36, 46, 31, 51, 39, 44, 49, 50, 42, 33, 37, 40], "transcript": [{"speaker": "Katie", "text": "So what do you think is a good age for girls to start wearing makeup?"}, {"speaker": "Aimee", "text": "I think it depends on the kind of makeup that they're wearing and the purpose, you know, because to me, it seems like there are two different kinds. You know, there are young children, young girls, young children, who wear play makeup, you know."}, {"speaker": "Katie", "text": "Yeah."}, {"speaker": "Aimee", "text": "It's a toy. It washes off easily, garish colors, very mild on the skin, and you know, it's literally just coloring in their face. It's not, you know, enhancing their features or trying to look as society thinks beautiful, you know. They're not covering up any pimples or spots, you know. It's not like that. It's just coloring in their face, trying to look more like a princess."}, {"speaker": "Aimee", "text": "And I have a six-year old daughter and she loves makeup. She has her own, like, young like toy makeup and she asks permission to wear it, and I let her wear it. I bought some for her. I make sure that she can only do it if she has a clean face and clean hands and that she washes off properly at the end. And that she tidies it away afterwards."}, {"speaker": "Katie", "text": "That's good."}, {"speaker": "Aimee", "text": "She's actually on her final warning because she used to leave it out – and I've warned her I will throw it in the bin. Because I have a toddler and she wants to see what her big sister is doing and she wants to play with it, so she grabs it and makes a mess everywhere. So yeah, six-year old is on her final warning."}, {"speaker": "Aimee", "text": "So I guess to answer your question, my six-year old is wearing her play makeup already. So it doesn't, yeah, it doesn't bother me. Young is –"}, {"speaker": "Katie", "text": "How old were you when you started wearing makeup?"}, {"speaker": "Aimee", "text": "Well, I love makeup, and that's probably where my daughter got it from. I wanted to wear makeup from a young age, the way my daughter does. I wasn't allowed. It was forbidden. And I first actually managed to buy a secret lipstick when I was about 9 or 10."}, {"speaker": "Katie", "text": "Secret lipstick."}, {"speaker": "Aimee", "text": "Yeah. I had to hide it from my mom, and she would only let me wear lip gloss when I was that age, and I wasn't allowed to wear any lip sticks, so I had to buy a secret one. And I was always so interested in my grandmother's makeup and my mom's makeup as well. But she never really wore much. She has a very simple sort of beauty routine."}, {"speaker": "Aimee", "text": "I'm much more interested in it than she is – she ever was. So I don't know where I inherited that from, but my daughter has definitely inherited that from me. So maybe because it was forbidden for me that's why I was drawn to it more."}, {"speaker": "Katie", "text": "Makes it more tantalizing."}, {"speaker": "Aimee", "text": "I think so. That could be it, but yeah, it's a real hobby for me. I really, really love it. I wish I had more money to purchase more. You can never have enough."}, {"speaker": "Katie", "text": "You can never have too many lipsticks."}, {"speaker": "Aimee", "text": "I know. It's true."}, {"speaker": "Katie", "text": "What do you think about boys wearing makeup?"}, {"speaker": "Aimee", "text": "If they want to wear makeup, then they should. Like it annoys me this horrible idea and concept of like men and boys have to be manly, like what is manly?"}, {"speaker": "Aimee", "text": "For me, makeup is an art. It really is. It's artistry. And, you know, if they want it, if they're feeling bad about their skin the way I feel bad about my skin, right. If I have pimples or spots, I'm lucky. I get to just cover up with like foundation and concealer, a bit of blusher. It makes me feel better."}, {"speaker": "Aimee", "text": "But, you know, if there's like a boy who has, you know, going through teenage years and he's got bad skin and he wants to cover up, and his macho friends catch him wearing it or whatever people in school catch him wearing it and it can be a really bad situation for him. And I think that is awful. It is really, really terrible. I think boys should wear makeup as they like."}, {"speaker": "Aimee", "text": "I actually follow quite a lot of makeup artists on social media. And I look at many, many pictures of different products and the art that they produce, and I follow male makeup artists as well. And the skills they have are unbelievable, honestly. The blending skills."}, {"speaker": "Katie", "text": "Their contouring."}, {"speaker": "Aimee", "text": "Yeah."}, {"speaker": "Katie", "text": "Oh my goodness."}, {"speaker": "Aimee", "text": "The blending skills and like covering up, you know, basically just like covering up their whole face and putting a new face on top of it."}, {"speaker": "Katie", "text": "It's pretty impressive."}, {"speaker": "Aimee", "text": "It's really impressive. It's so amazing. I would really enjoy a makeup lesson from some of the artists that I follow on different social media sites."}, {"speaker": "Katie", "text": "Absolutely."}], "speakerEvidence": ["Assets/speakers/UK-SC-Amy.jpg", "Assets/speakers/UK-Katie.png", "Assets/flags/flag-scotland.png", "Assets/flags/flag-england.png"], "sourceLevelText": "Views #1447  | Intermediate (B1)", "originalTitle": "Get More Lessons Here &gt;&gt;"}];
